#!/usr/bin/env python3
"""Safely add soil-choice localization to the currently uploaded ECHOREPO map.js.

Supports both Unix LF and Windows CRLF without changing unrelated code.
Defaults to dry-run. --apply makes a backup and writes the change atomically.
"""
import argparse
import difflib
import os
import sys
import tempfile
from pathlib import Path

INSERT = "\n  // Soil texture and structure choices come from the Flutter dictionaries.\n  // This JSON is generated by tools/normalize_soil_classifications.py.\n  // The reverse index includes the reviewed synonyms and Greek corrections.\n  let soilClassifications = null;\n  const SOIL_I18N_URL = cfg.soil_classifications_url || '/static/soil_classifications_i18n.json';\n  const SOIL_LOCALE = String(\n    cfg.current_locale || window.I18N?.locale || document.documentElement.lang || 'en'\n  ).replace(/-/g, '_');\n\n  function normalizeSoilChoice(value) {\n    // Match the Python script's Unicode casefold/dash/asterisk normalization.\n    // Greek lowercasing produces final sigma (ς), while Python casefold uses σ.\n    return String(value ?? '')\n      .normalize('NFKC')\n      .toLowerCase()\n      .replace(/[\\u2010-\\u2015\\u2212\\uFE58\\uFE63\\uFF0D-]/g, ' ')\n      .replace(/\\u03C2/g, '\\u03C3')\n      .trim()\n      .replace(/\\s+/g, ' ')\n      .replace(/\\s*\\*\\s*$/, ' *');\n  }\n\n  function getSoilLocaleDict(field) {\n    const locales = soilClassifications?.locales || {};\n    const wanted = SOIL_LOCALE.toLowerCase();\n    const match = Object.keys(locales).find(loc => loc.toLowerCase() === wanted);\n    if (match) return locales[match][field] || {};\n\n    const language = wanted.split('_')[0];\n    const preferred = language === 'el' ? 'el_GR'\n      : ['nb', 'no', 'nn'].includes(language) ? 'nb_NO' : null;\n    if (preferred && locales[preferred]) return locales[preferred][field] || {};\n    const fallback = Object.keys(locales).find(loc => loc.toLowerCase().split('_')[0] === language);\n    return fallback ? locales[fallback][field] || {} : {};\n  }\n\n  function localizeSoilChoice(field, englishValue, originalValue) {\n    const fallback = englishValue || originalValue;\n    if (!fallback || !soilClassifications) return fallback;\n\n    const reverse = soilClassifications.reverse?.[field] || {};\n    // Prefer a canonical English value if present; legacy /my records may\n    // supply only the original Flutter value. Never guess unknown text.\n    const key = reverse[normalizeSoilChoice(englishValue)] ||\n      reverse[normalizeSoilChoice(originalValue)];\n    if (!key) return fallback;\n\n    const english = soilClassifications.english?.[field]?.[key] || key;\n    const translated = getSoilLocaleDict(field)[key] || english;\n    // The app's Other * option includes an input-field marker; hide that\n    // marker in map popup values in every language.\n    return key === 'Other *'\n      ? translated.replace(/\\s*\\*\\s*$/, '').trim()\n      : translated;\n  }\n\n  // Loading this resource must never prevent the map from showing samples.\n  // If unavailable, popups fall back to the existing raw/English values.\n  fetch(SOIL_I18N_URL, { credentials: 'same-origin', cache: 'no-cache' })\n    .then(response => {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    })\n    .then(data => {\n      if (!data || data.schema_version !== 1 || !data.reverse || !data.locales) {\n        throw new Error('Unsupported soil-classification dictionary');\n      }\n      soilClassifications = data;\n      // Refresh the current popup if it opened before the dictionary loaded.\n      const popup = map._popup;\n      const layer = popup?._source;\n      if (popup?.isOpen?.() && layer?.feature) {\n        popup.setContent(formatPopup(layer.feature, !!layer.__owner));\n        setTimeout(() => initPopupTooltips(popup), 0);\n      }\n    })\n    .catch(error => console.warn('Soil-classification localization unavailable:', error));\n"
OLD_POPUP = '    const texture = pick(\n      p.SOIL_TEXTURE_texture,\n      p.soil_texture_en, p.soil_texture_orig,\n      p.texture_en, p.texture_orig,\n      p.texture\n    );\n\n    const structure = pick(\n      p.SOIL_STRUCTURE_structure,\n      p.soil_structure_en, p.soil_structure_orig,\n      p.structure_en, p.structure_orig,\n      p.structure\n    );'
NEW_POPUP = "    const texture = localizeSoilChoice(\n      'texture',\n      pick(p.soil_texture_en, p.texture_en),\n      pick(p.soil_texture_orig, p.SOIL_TEXTURE_texture, p.texture_orig, p.texture)\n    );\n\n    const structure = localizeSoilChoice(\n      'structure',\n      pick(p.soil_structure_en, p.structure_en),\n      pick(p.soil_structure_orig, p.SOIL_STRUCTURE_structure, p.structure_orig, p.structure)\n    );"
ANCHOR = "  const cfg = window.ECHOREPO_CFG || {};\n"

def transform(text):
    if 'function localizeSoilChoice(' in text:
        raise ValueError('Soil localization already appears installed. Nothing changed.')
    if text.count(ANCHOR) < 1:
        raise ValueError('Cannot find map config anchor: this map.js differs from the uploaded version.')
    if text.count(OLD_POPUP) != 1:
        raise ValueError('Cannot find exact texture/structure popup block: this map.js differs from the uploaded version.')
    text = text.replace(ANCHOR, ANCHOR + INSERT, 1)
    text = text.replace(OLD_POPUP, NEW_POPUP, 1)
    return text

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--file', type=Path, default=Path('static/js/map.js'))
    ap.add_argument('--apply', action='store_true')
    args = ap.parse_args()
    path = args.file
    raw = path.read_bytes()
    crlf = b'\r\n' in raw
    if crlf and b'\n' in raw.replace(b'\r\n', b''):
        raise ValueError('Mixed line endings detected; please normalize the file first')
    before = raw.decode('utf-8-sig').replace('\r\n','\n')
    after = transform(before)
    diff = ''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile=str(path),tofile=str(path)))
    print(diff)
    if not args.apply:
        print('DRY RUN: file not modified. Use --apply to install.')
        return 0
    payload = after.replace('\n','\r\n' if crlf else '\n').encode('utf-8')
    backup = path.with_name(path.name + '.soil-localization.bak')
    if backup.exists():
        raise FileExistsError(f'Backup exists; refusing to overwrite: {backup}')
    backup.write_bytes(raw)
    fd, name = tempfile.mkstemp(prefix='.'+path.name+'.', dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(payload)
        os.chmod(name, path.stat().st_mode & 0o777)
        os.replace(name,path)
    finally:
        if os.path.exists(name): os.unlink(name)
    print(f'Applied to {path}, preserving {"CRLF" if crlf else "LF"} line endings. Backup: {backup}')
    return 0

if __name__ == '__main__':
    try: sys.exit(main())
    except (OSError,ValueError) as exc:
        print('ERROR:',exc,file=sys.stderr)
        sys.exit(1)
